def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==8]
    for r in range(h):
        cs=[c for rr,c in pts if rr==r]
        if len(cs)>1:
            for c in range(min(cs)+1,max(cs)):
                if grid[r][c]==7: out[r][c]=3
    for c in range(w):
        rs=[r for r,cc in pts if cc==c]
        if len(rs)>1:
            for r in range(min(rs)+1,max(rs)):
                if grid[r][c]==7: out[r][c]=3
    return out
